package com.cowave.search.outbound_adapter.proxy

import com.cowave.search.client.proxy_api.ProxyApiClient
import com.cowave.search.client.proxy_api.ProxyApiClientConfig
import com.cowave.search.client.proxy_api.ProxyApiClientProperties
import com.cowave.search.domain.proxy.category.CategoryRepository
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.boot.test.context.SpringBootTest

@SpringBootTest(
    classes = [
        ProxyApiClientConfig::class,
        ProxyApiClient::class,
        CategoryRepositoryImpl::class,
    ]
)
@EnableConfigurationProperties(
    ProxyApiClientProperties::class,
)
class CategoryRepositoryImpTest(
    private val repository: CategoryRepository
) : FunSpec({
    /**
     * expected response: [{id=10718, name=물안경, depth=4}, {id=10722, name=오리발, depth=4}]
     */
    test("GraphQL get categories query test") {
        val list = repository.findAllByIds(listOf(10718, 10722))

        list.size shouldBe 2
        list[0].depth shouldBe 4
    }
})

