                result shouldBe true
            }
            test("복합 키워드 테스트(false) ") {
                val result =
                    UsedRentalDetector.isUsedOrRentalForProduct(
                        name = "노트북 인터넷 쇼핑몰",
                    )

                result shouldBe false
            }
        }
    })

