package com.cowave.search.repository.cache.tiered

import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import io.mockk.every
import io.mockk.mockk
import io.mockk.verify

class TieredCacheImplTest : FunSpec({

    lateinit var l1: CaffeineLocalCache<Int, String>
    lateinit var l2: ValkeyRemoteCache<Int, String>
    lateinit var cache: TieredCacheImpl<Int, String>

    val idExtractor: (String) -> Int = { it.hashCode() }

    beforeEach {
        l1 = mockk(relaxed = true)
        l2 = mockk(relaxed = true)
        cache = TieredCacheImpl(l1, l2, idExtractor)
    }

    context("TieredCacheImpl") {
        test("모든 ID가 L1에 있으면 L2와 fetcher를 호출하지 않는다") {
            val ids = listOf(1, 2, 3)
            every { l1.getAll(ids) } returns mapOf(1 to "a", 2 to "b", 3 to "c")

            val fetcher = mockk<(List<Int>) -> List<String>>()

            val result = cache.getOrFetch(ids, fetcher)

            result shouldBe listOf("a", "b", "c")
            verify(exactly = 0) { l2.getAll(any()) }
            verify(exactly = 0) { fetcher(any()) }
        }

        test("L1 미스 후 L2에서 조회하고, L1에 채운다") {
            val ids = listOf(1, 2)
            every { l1.getAll(ids) } returns emptyMap()
            every { l2.getAll(ids) } returns mapOf(1 to "a", 2 to "b")

            val fetcher = mockk<(List<Int>) -> List<String>>()

            val result = cache.getOrFetch(ids, fetcher)

            result shouldBe listOf("a", "b")
            verify { l1.putAll(mapOf(1 to "a", 2 to "b")) }
            verify(exactly = 0) { fetcher(any()) }
        }

        test("L1, L2 모두 미스 시 fetcher를 호출하고 L1, L2 모두 채운다") {
            val ids = listOf(1, 2)
            every { l1.getAll(ids) } returns emptyMap()
            every { l2.getAll(ids) } returns emptyMap()

            val fetched = listOf("a", "b")
            val fetchedMap = fetched.associateBy(idExtractor)
            val fetcher = mockk<(List<Int>) -> List<String>>()
            every { fetcher(ids) } returns fetched

            val result = cache.getOrFetch(ids, fetcher)

            result shouldBe ids.mapNotNull { fetchedMap[it] }
            verify { l1.putAll(fetchedMap) }
            verify { l2.putAll(fetchedMap) }
        }

        test("부분 캐시 히트 시 미스된 ID만 fetcher에 전달한다") {
            val ids = listOf(1, 2, 3)
            every { l1.getAll(ids) } returns mapOf(1 to "a")
            every { l2.getAll(listOf(2, 3)) } returns mapOf(2 to "b")

            val fetcher = mockk<(List<Int>) -> List<String>>()
            every { fetcher(listOf(3)) } returns listOf("c")

            val result = cache.getOrFetch(ids, fetcher)

            result shouldBe listOf("a", "b", "c")
            verify { fetcher(listOf(3)) }
        }

        test("빈 리스트 입력 시 빈 리스트를 반환한다") {
            val fetcher = mockk<(List<Int>) -> List<String>>()

            val result = cache.getOrFetch(emptyList(), fetcher)

            result shouldBe emptyList()
            verify(exactly = 0) { l1.getAll(any()) }
            verify(exactly = 0) { l2.getAll(any()) }
            verify(exactly = 0) { fetcher(any()) }
        }
    }
})

package com.cowave.search.outbound_adapter.proxy.cache

import com.cowave.search.domain.proxy.category.Category
import com.cowave.search.domain.proxy.category.CategoryRepository
import com.cowave.search.repository.cache.tiered.TieredCache
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import io.mockk.every
import io.mockk.mockk
import io.mockk.slot
import io.mockk.verify

class CachingCategoryRepositoryTest : FunSpec({

    val delegate = mockk<CategoryRepository>()
    val cache = mockk<TieredCache<Int, Category>>()
    val repository = CachingCategoryRepository(delegate, cache)

    val category1 = Category(id = 1, name = "TV", depth = 1, idPath = "1", namePath = "TV", status = "USE")
    val category2 = Category(id = 2, name = "냉장고", depth = 1, idPath = "2", namePath = "냉장고", status = "USE")

    context("CachingCategoryRepository") {
        test("캐시가 결과를 반환하면 delegate를 호출하지 않는다") {
            val ids = listOf(1, 2)
            val fetcherSlot = slot<(List<Int>) -> List<Category>>()
            every { cache.getOrFetch(ids, capture(fetcherSlot)) } returns listOf(category1, category2)

            val result = repository.findAllByIds(ids)

            result shouldBe listOf(category1, category2)
            verify(exactly = 0) { delegate.findAllByIds(any()) }
        }

        test("캐시 미스 시 delegate의 findAllByIds를 호출한다") {
            val ids = listOf(1, 2)
            val fetcherSlot = slot<(List<Int>) -> List<Category>>()
            every { cache.getOrFetch(ids, capture(fetcherSlot)) } answers {
                fetcherSlot.captured.invoke(ids)
            }
            every { delegate.findAllByIds(ids) } returns listOf(category1, category2)

            val result = repository.findAllByIds(ids)

            result shouldBe listOf(category1, category2)
            verify(exactly = 1) { delegate.findAllByIds(ids) }
        }
    }
})

