package com.cowave.search.repository.cache.tiered

import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.collections.shouldBeEmpty
import io.kotest.matchers.collections.shouldContainExactly
import io.kotest.matchers.shouldBe
import io.mockk.every
import io.mockk.mockk
import io.mockk.verify

class TieredCacheImplTest : FunSpec({

    data class Item(val id: Int, val name: String)

    val idExtractor: (Item) -> Int = { it.id }

    context("getOrFetch") {
        test("빈 리스트 입력 시 빈 리스트를 반환한다") {
            val l1 = mockk<CaffeineLocalCache<Int, Item>>()
            val l2 = mockk<ValkeyRemoteCache<Int, Item>>()
            val cache = TieredCacheImpl(l1, l2, idExtractor)
            val fetcher = mockk<(List<Int>) -> List<Item>>()

            val result = cache.getOrFetch(emptyList(), fetcher)

            result.shouldBeEmpty()
            verify(exactly = 0) { l1.getAll(any()) }
            verify(exactly = 0) { l2.getAll(any()) }
            verify(exactly = 0) { fetcher(any()) }
        }

        test("모든 ID가 L1에 있으면 L2와 fetcher를 호출하지 않는다") {
            val l1 = mockk<CaffeineLocalCache<Int, Item>>()
            val l2 = mockk<ValkeyRemoteCache<Int, Item>>()
            val cache = TieredCacheImpl(l1, l2, idExtractor)
            val fetcher = mockk<(List<Int>) -> List<Item>>()

            val item1 = Item(1, "A")
            val item2 = Item(2, "B")
            every { l1.getAll(listOf(1, 2)) } returns mapOf(1 to item1, 2 to item2)

            val result = cache.getOrFetch(listOf(1, 2), fetcher)

            result shouldContainExactly listOf(item1, item2)
            verify(exactly = 0) { l2.getAll(any()) }
            verify(exactly = 0) { fetcher(any()) }
        }

        test("L1 미스 후 L2에서 조회하고 L1에 채운다") {
            val l1 = mockk<CaffeineLocalCache<Int, Item>>(relaxed = true)
            val l2 = mockk<ValkeyRemoteCache<Int, Item>>()
            val cache = TieredCacheImpl(l1, l2, idExtractor)
            val fetcher = mockk<(List<Int>) -> List<Item>>()

            val item1 = Item(1, "A")
            val item2 = Item(2, "B")
            every { l1.getAll(listOf(1, 2)) } returns mapOf(1 to item1)
            every { l2.getAll(listOf(2)) } returns mapOf(2 to item2)

            val result = cache.getOrFetch(listOf(1, 2), fetcher)

            result shouldContainExactly listOf(item1, item2)
            verify { l1.putAll(mapOf(2 to item2)) }
            verify(exactly = 0) { fetcher(any()) }
        }

        test("L1 L2 모두 미스 시 fetcher를 호출하고 L1 L2 모두 채운다") {
            val l1 = mockk<CaffeineLocalCache<Int, Item>>(relaxed = true)
            val l2 = mockk<ValkeyRemoteCache<Int, Item>>(relaxed = true)
            val cache = TieredCacheImpl(l1, l2, idExtractor)

            val item1 = Item(1, "A")
            every { l1.getAll(listOf(1)) } returns emptyMap()
            every { l2.getAll(listOf(1)) } returns emptyMap()

            val result = cache.getOrFetch(listOf(1)) { listOf(item1) }

            result shouldBe listOf(item1)
            verify { l1.putAll(mapOf(1 to item1)) }
            verify { l2.putAll(mapOf(1 to item1)) }
        }

        test("부분 캐시 히트 시 미스된 ID만 fetcher에 전달한다") {
            val l1 = mockk<CaffeineLocalCache<Int, Item>>(relaxed = true)
            val l2 = mockk<ValkeyRemoteCache<Int, Item>>(relaxed = true)
            val cache = TieredCacheImpl(l1, l2, idExtractor)

            val item1 = Item(1, "A")
            val item2 = Item(2, "B")
            val item3 = Item(3, "C")

            every { l1.getAll(listOf(1, 2, 3)) } returns mapOf(1 to item1)
            every { l2.getAll(listOf(2, 3)) } returns mapOf(2 to item2)

            val fetchedIds = mutableListOf<Int>()
            val result = cache.getOrFetch(listOf(1, 2, 3)) { ids ->
                fetchedIds.addAll(ids)
                listOf(item3)
            }

            result shouldContainExactly listOf(item1, item2, item3)
            fetchedIds shouldContainExactly listOf(3)
        }
    }
})

